/**
 * @name Param to file/command sink
 * @kind problem
 * @problem.severity warning
 * @id py/param-sink
 */
import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module C implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node s) { s instanceof DataFlow::ParameterNode and s.getLocation().getFile().getBaseName() in ["main.py","cli.py"] }
  predicate isSink(DataFlow::Node s) {
    s = any(FileSystemAccess fa).getAPathArgument() or
    s = any(SystemCommandExecution c).getCommand()
  }
}
module F = TaintTracking::Global<C>;
from DataFlow::Node s, DataFlow::Node k
where F::flow(s, k)
select k, "Flow from param at line " + s.getLocation().getStartLine() + " (" + s.getLocation().getFile().getBaseName() + ") to sink"
